<?php
require_once __DIR__ . '/../../include/auth_user.php';
$role='User';$area='user';$activeMenu='arsip';$pageTitle='Arsip Surat';
$q=trim((string)($_GET['q']??''));$like='%'.$q.'%';$year=trim((string)($_GET['tahun']??''));if($year!=='' && !preg_match('/^20\d{2}$/',$year))$year='';
$typeFilter=trim((string)($_GET['jenis']??''));if(!in_array($typeFilter,['Masuk','Keluar'],true))$typeFilter='';
$page=max(1,(int)($_GET['page']??1));$perPage=10;
$count=$conn->prepare("SELECT COUNT(*) AS total FROM arsip_surat a JOIN surat s ON s.id=a.surat_id WHERE s.status='Selesai' AND (?='' OR s.jenis_surat=?) AND (?='' OR s.nomor_surat LIKE ? OR s.perihal LIKE ? OR s.pengirim LIKE ? OR s.tujuan LIKE ?) AND (?='' OR a.tahun_arsip=?)");
$count->bind_param('sssssssss',$typeFilter,$typeFilter,$q,$like,$like,$like,$like,$year,$year);$count->execute();$total=(int)$count->get_result()->fetch_assoc()['total'];$count->close();
$totalPages=max(1,(int)ceil($total/$perPage));$page=min($page,$totalPages);$offset=($page-1)*$perPage;
$stmt=$conn->prepare("SELECT a.id AS archive_id,a.tahun_arsip,a.lokasi_arsip,a.keterangan AS keterangan_arsip,a.archived_at,s.* FROM arsip_surat a JOIN surat s ON s.id=a.surat_id WHERE s.status='Selesai' AND (?='' OR s.jenis_surat=?) AND (?='' OR s.nomor_surat LIKE ? OR s.perihal LIKE ? OR s.pengirim LIKE ? OR s.tujuan LIKE ?) AND (?='' OR a.tahun_arsip=?) ORDER BY a.archived_at DESC LIMIT ? OFFSET ?");
$stmt->bind_param('sssssssssii',$typeFilter,$typeFilter,$q,$like,$like,$like,$like,$year,$year,$perPage,$offset);$stmt->execute();$rows=$stmt->get_result();
$years=$conn->query('SELECT DISTINCT tahun_arsip FROM arsip_surat ORDER BY tahun_arsip DESC');
require __DIR__ . '/../../include/header.php';
?>
<div class="page-heading"><div><h1>Arsip Surat</h1><p>Daftar surat yang telah selesai diproses dan diarsipkan.</p><div class="breadcrumbs"><a href="<?= BASE_URL ?>/<?= $area ?>/dashboard.php">Dashboard</a><span>›</span>Arsip Surat</div></div></div>
<div class="mini-stats"><div><span>Total Arsip</span><strong><?= number_format($total) ?></strong></div><div><span>Arsip Surat Masuk</span><?php $c=$conn->query("SELECT COUNT(*) jumlah FROM arsip_surat a JOIN surat s ON s.id=a.surat_id WHERE s.jenis_surat='Masuk' AND s.status='Selesai'")->fetch_assoc(); ?><strong><?= number_format((int)$c['jumlah']) ?></strong></div><div><span>Arsip Surat Keluar</span><?php $c=$conn->query("SELECT COUNT(*) jumlah FROM arsip_surat a JOIN surat s ON s.id=a.surat_id WHERE s.jenis_surat='Keluar' AND s.status='Selesai'")->fetch_assoc(); ?><strong><?= number_format((int)$c['jumlah']) ?></strong></div><div><span>Tahun Arsip</span><strong><?= date('Y') ?></strong></div></div>
<section class="panel filter-panel"><div class="panel-heading"><div><h2>Temukan Arsip</h2><p>Cari berdasarkan nomor, perihal, pengirim/tujuan, jenis, atau tahun arsip.</p></div></div><form class="filter-form archive-filter" method="get"><label class="search-input"><span>⌕</span><input type="search" name="q" value="<?= htmlspecialchars($q,ENT_QUOTES,'UTF-8') ?>" placeholder="Nomor surat atau perihal..."></label><select name="jenis"><option value="">Semua Jenis</option><option value="Masuk" <?= $typeFilter==='Masuk'?'selected':'' ?>>Surat Masuk</option><option value="Keluar" <?= $typeFilter==='Keluar'?'selected':'' ?>>Surat Keluar</option></select><select name="tahun"><option value="">Semua Tahun</option><?php while($yr=$years->fetch_assoc()): ?><option value="<?= (int)$yr['tahun_arsip'] ?>" <?= $year==(string)$yr['tahun_arsip']?'selected':'' ?>><?= (int)$yr['tahun_arsip'] ?></option><?php endwhile; ?></select><div class="filter-actions"><button class="button button-dark" type="submit">Cari</button><a class="button button-light" href="<?= BASE_URL ?>/<?= $area ?>/arsip_surat/index.php">Reset</a><a class="button button-light" href="<?= BASE_URL ?>/proses/surat_export.php?jenis=<?= urlencode($typeFilter) ?>&q=<?= urlencode($q) ?>&arsip=1&tahun=<?= urlencode($year) ?>">Export CSV</a></div></form></section>
<section class="panel"><div class="panel-heading"><div><h2>Daftar Arsip</h2><p>Menampilkan <?= $total?$offset+1:0 ?>–<?= min($offset+$perPage,$total) ?> dari <?= number_format($total) ?> data.</p></div></div><?php if($rows->num_rows>0): ?><div class="table-wrap"><table><thead><tr><th>No.</th><th>Nomor Surat</th><th>Jenis</th><th>Perihal</th><th>Tanggal Surat</th><th>Tahun Arsip</th><th>Tanggal Diarsipkan</th><th>Aksi</th></tr></thead><tbody><?php $no=$offset+1;while($row=$rows->fetch_assoc()): ?><tr><td><?= $no++ ?></td><td class="cell-strong"><?= htmlspecialchars($row['nomor_surat'],ENT_QUOTES,'UTF-8') ?></td><td><?= $row['jenis_surat']==='Masuk'?'Masuk':'Keluar' ?></td><td><?= htmlspecialchars($row['perihal'],ENT_QUOTES,'UTF-8') ?></td><td><?= date('d-m-Y',strtotime($row['tanggal_surat'])) ?></td><td><?= (int)$row['tahun_arsip'] ?></td><td><?= date('d-m-Y H:i',strtotime($row['archived_at'])) ?></td><td><a class="button-small" href="<?= BASE_URL ?>/<?= $area ?>/arsip_surat/detail.php?id=<?= (int)$row['id'] ?>">Detail Arsip</a></td></tr><?php endwhile; ?></tbody></table></div><?php else: ?><div class="empty-state">Belum ada arsip yang cocok dengan filter ini.</div><?php endif; ?><?php if($totalPages>1): ?><nav class="pagination" aria-label="Paginasi"><?php for($p=1;$p<=$totalPages;$p++):$params=$_GET;$params['page']=$p; ?><a class="<?= $p===$page?'current':'' ?>" href="?<?= htmlspecialchars(http_build_query($params),ENT_QUOTES,'UTF-8') ?>"><?= $p ?></a><?php endfor; ?></nav><?php endif; ?></section>
<?php require __DIR__ . '/../../include/footer.php'; ?>
